/*
 * The configuration's shape, in one place.
 *
 * Three things are derived from what is written here: the parse every
 * configuration is admitted by, the TypeScript types the application reads
 * configuration through, and the references an operator writes their
 * configuration from — `env.example`, `portal.config.example.json` and the
 * JSON Schema `portal.config.schema.json`, all generated by
 * `pnpm config:generate`. Adding a setting means adding it here and
 * regenerating, rather than writing it into a type, a check and reference files
 * that are free to disagree.
 *
 * A `describe()` string is operator-facing: it is what the generated references
 * carry beside the setting, and what a load error quotes. Where one names
 * another setting, it names the variable rather than the key, since the variable
 * is the spelling an operator types and the one a JSON file's key is easy to
 * read off.
 *
 * The configuration arrives as environment variables, assembled into the nested
 * document this schema describes by ./env, which maps
 * `PORTAL_TENANT_ACME_OAUTH_GOOGLE_CLIENT_ID` onto
 * `tenants.acme.oauth.google.clientId`, and as portal.config*.json files, read
 * by ./files, which hold that document as it is. Keys here stay camelCase for
 * the application's sake and the files'; the mapping is what spells them for
 * the environment.
 */

import path from 'path';

import {z} from 'zod';

import {
  getMaxConnections,
  mailAccountKey,
} from '@/lib/core/notification/mail-account';
import {
  isReservedSegment,
  reservedSegments,
} from '@/lib/core/path/reserved-segments';
import {canonicalHost} from '@/tenant/routing';

import {envNameFor, TENANTS_KEY} from './names';

/*
 * A tenant id is the URL path segment the tenant is served under, and the
 * segment of every variable that configures it.
 *
 * Lowercase letters and digits only, opening with a letter. The environment
 * decides most of that: a variable name is uppercased and split on underscores,
 * so an id holding either would never round-trip, and a hyphen cannot be typed
 * into a shell's `export`. The proxy reads the first segment of an address as a
 * tenant name, so the leading letter keeps `_next`, `_not-found`, a digit or a
 * dot from looking like one; the proxy's own pattern is wider, and an id it
 * matches that this refuses resolves no tenant, which is the right answer.
 */
const TENANT_ID_PATTERN = /^[a-z][a-z0-9]*$/;

/* Reserving the whole width a payment context id can reach: a Hub PISP payment
 * carries `${contextId}-${tenantId}` in a field of 35 characters, and a context
 * id is a bigint sequence, so its 19 digits and the separator leave 15. */
const TENANT_ID_MAX_LENGTH = 15;

/*
 * A positive whole number.
 *
 * Rejected at load rather than corrected at the point of use: a setting
 * silently replaced by a default is how a deployment ends up believing it set
 * three and running at ten.
 */
const positiveInteger = () => z.int().min(1);

/*
 * The hostnames the auth library's own host check accepts: DNS labels of at
 * most 63 characters, an IPv4 literal (which those labels already cover), or a
 * bracketed IPv6 literal. An underscore is the character that occurs in
 * practice and is not among them.
 */
const HOSTNAME_PATTERN =
  /^(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*|\[[0-9a-fA-F:]+\])$/;

/*
 * Whether a value is an origin this deployment can be reached at, spelled the
 * way an origin is spelled.
 *
 * Exactness matters because nothing parses the value again. Absolute addresses
 * are built by concatenating onto it, so anything trailing the host survives into
 * them: a lone trailing slash emails `<host>//auth/reset-password/…`, which
 * matches no tenant and no reserved segment, so the proxy answers not-found.
 * Stored workspace addresses are matched by string prefix against it, so a
 * spelling that differs from the canonical one — a default port written out, an
 * uppercase host — matches none of them and the tenant resolves no workspace.
 *
 * Refused rather than corrected to the canonical spelling, because this value is
 * typed into AOS as well, as the prefix of every workspace address held there.
 * Repairing only the copy here would leave the two disagreeing.
 *
 * The host is restricted to what the auth library accepts, because one it
 * refuses is resolved from the request URL by the request handler and from the
 * configured origin by a server-side session read. An OAuth redirect address
 * built under the first is not the one registered under the second, and the
 * identity provider refuses it.
 */
function isDeploymentOrigin(value: string): boolean {
  return parseOrigin(value) !== null;
}

/* The parsed form of an origin, or null for a value that is not one. Callers
 * that need to read a part of it go through this rather than `new URL`, which
 * throws — and a throw raised while the configuration is being checked escapes
 * the parse, so a mistyped origin would be reported as an unhandled TypeError
 * naming neither the variable nor the tenant. */
function parseOrigin(value: unknown): URL | null {
  if (typeof value !== 'string') return null;

  let url: URL;

  try {
    url = new URL(value);
  } catch {
    return null;
  }

  /* An origin holds a scheme and a host and can hold nothing else, so equality
   * with the parsed origin settles the trailing characters and the canonical
   * spelling at once. It settles nothing about the scheme: `ftp://`, `ws://` and
   * `wss://` each parse to an origin equal to what was written, so the protocol
   * test beside it is what admits only the two a deployment is served over.
   *
   * Ports 80 and 443 are refused however they are written. A scheme's own port
   * fails the equality (`new URL` leaves it off the origin), and the crossed
   * spellings — https on 80, http on 443 — parse but can never be reached: a
   * Host header carries no scheme, so request routing treats both ports as
   * default and would strip what the configuration declared. */
  const isOrigin =
    (url.protocol === 'http:' || url.protocol === 'https:') &&
    value === url.origin &&
    url.port !== '80' &&
    url.port !== '443' &&
    HOSTNAME_PATTERN.test(url.hostname);

  return isOrigin ? url : null;
}

const ORIGIN_ERROR =
  'must be written as an origin — a scheme and a host, with no path, query, ' +
  'fragment or trailing slash, e.g. https://portal.example.com. Ports 80 and ' +
  '443 are the defaults and are left off';

/* The variable carrying a setting, for descriptions and messages. */
const name = envNameFor;

/**
 * What the browser is handed about a tenant.
 *
 * Membership in this group is what marks a value as safe to send to a browser:
 * everything here reaches every visitor's page, and nothing outside it does.
 * Groups mirror the server-side ones they pair with — `paypal` beside
 * `payments.paypal`, `webPush.publicKey` beside `webPush.privateKey` — so the
 * two halves of one credential are found under one name.
 */
const publicConfigSchema = z
  .strictObject({
    host: z
      .string()
      .min(1)
      .refine(isDeploymentOrigin, {error: ORIGIN_ERROR})
      .describe(
        `Origin this tenant is served on, e.g. https://portal.example.com — scheme and host only, with no trailing slash. Workspace URLs are stored against it, every absolute link is built from it, and the deployment trusts it as an origin to authenticate on, so a tenant without one resolves no workspace. Tenants sharing an origin is the ordinary case; the scheme must be the one ${name(['origin'])} carries.`,
      ),
    paypal: z
      .strictObject({
        clientId: z
          .string()
          .min(1)
          .describe(
            "The PayPal client id the browser's checkout button is created with. Public by design; the secret stays in the payments group.",
          ),
      })
      .optional(),
    webPush: z
      .strictObject({
        publicKey: z
          .string()
          .min(1)
          .describe(
            `The VAPID public key a browser subscribes with. Pairs with ${name([TENANTS_KEY, '<id>', 'webPush', 'privateKey'])}; both are needed for notifications.`,
          ),
      })
      .optional(),
    mattermost: z
      .strictObject({
        host: z
          .string()
          .min(1)
          .describe('Mattermost address the sidebar links to.'),
      })
      .optional(),
    keycloak: z
      .strictObject({
        buttonLabel: z
          .string()
          .describe(
            'Text of the Keycloak sign-in button; defaults to "Log In with Keycloak".',
          )
          .optional(),
        buttonImage: z
          .string()
          .describe(
            'Address of the image shown on the Keycloak sign-in button; defaults to the bundled Keycloak mark.',
          )
          .optional(),
      })
      .optional(),
    links: z
      .strictObject({
        linkedin: z.string().optional(),
        twitter: z.string().optional(),
        instagram: z.string().optional(),
        whatsapp: z.string().optional(),
      })
      .describe('Social addresses the news application offers to share to.')
      .optional(),
  })
  .describe(
    'Browser-facing settings for this tenant. Everything in this group is sent to every visitor; nothing outside it is.',
  );

const aosAuthSchema = z
  .strictObject({
    apiKey: z.string().optional(),
    username: z.string().optional(),
    password: z.string().optional(),
  })
  .refine(auth => !!auth.apiKey || !!(auth.username && auth.password), {
    error: 'requires an API key, or a username and a password',
  })
  .describe(
    'AOS credentials: an API key (AOS 9+, generated in AOS under Preferences → API Keys), or a username and password for basic auth. The API key wins when both are set.',
  );

const aosSchema = z
  .strictObject({
    url: z
      .string()
      .min(1)
      .describe(
        'Base URL of the AOS instance, e.g. https://erp.example.com/axelor-erp. Unique per tenant in topology A (dedicated AOS); shared across tenants in topology B (AOS multi-tenancy).',
      ),
    tenantId: z
      .string()
      .describe(
        'AOS-side tenant id — independent of the portal tenant id. Set it when this tenant lives on a shared AOS instance with AOS multi-tenancy (topology B): every AOS call then carries X-Tenant-ID with this value. Leave unset for a dedicated AOS instance (topology A).',
      )
      .optional(),
    storage: z
      .string()
      .min(1)
      .describe(
        `The AOS instance's data.upload.dir base path (created on first connect; back it with a mounted volume so uploads survive). When ${name([TENANTS_KEY, '<id>', 'aos', 'tenantId'])} is set (topology B), the portal reads and writes files under <storage>/<tenantId> to match AOP's per-tenant subdirectory; a dedicated instance (topology A) uses this path as-is.`,
      ),
    auth: aosAuthSchema,
    webhookSecret: z
      .string()
      .describe(
        'Secret AOS uses to sign notification webhooks for this tenant. Set the same value in the AOS portal configuration.',
      )
      .optional(),
  })
  /* Bake the per-tenant storage root once, mirroring AOP's
   * FileSystemStore.getRootPath(): a tenant on a shared multi-tenant AOS keeps
   * its files under <data.upload.dir>/<tenantId>, while a dedicated instance
   * (or the AOP "default" tenant) uses <data.upload.dir> as-is. The portal reads
   * and writes the AOS filesystem directly, so every storage consumer can use
   * config.aos.storage verbatim without re-deriving the subdirectory. */
  .transform(aos => ({
    ...aos,
    storage:
      aos.tenantId && aos.tenantId !== 'default'
        ? path.join(aos.storage, aos.tenantId)
        : aos.storage,
  }));

