const mailSchema = z
  .strictObject({
    host: z.string().min(1),
    port: positiveInteger()
      .max(65535)
      .describe(
        'TCP port the SMTP server listens on, commonly 587 for STARTTLS or 465 with secure set.',
      ),
    secure: z.boolean().optional(),
    user: z.string().min(1),
    password: z.string().min(1),
    email: z.string().describe('From address; defaults to user.').optional(),
    maxConnections: positiveInteger()
      .describe(
        "Connections this tenant's mail account may hold open at once. A mail server limits concurrency per sender, so the ceiling belongs to the account — a Microsoft 365 mailbox allows three. Tenants sharing a mailbox share one pool and one ceiling, so they must agree on this value or the configuration is refused at startup. Defaults to 10.",
      )
      .optional(),
  })
  .describe('Per-tenant SMTP settings.');

const oauthSchema = z
  .strictObject({
    google: z
      .strictObject({
        clientId: z.string().min(1),
        clientSecret: z.string().min(1),
      })
      .optional(),
    keycloak: z
      .strictObject({
        clientId: z.string().min(1),
        clientSecret: z.string().min(1),
        issuer: z
          .string()
          .min(1)
          .describe(
            'Keycloak realm issuer URL, with or without a trailing slash. Each tenant uses its own realm.',
          )
          /* A trailing slash and no trailing slash are two spellings of the same
           * issuer and both correct. Settled to one of them so the discovery
           * address built from it is well-formed either way: the doubled slash
           * the other spelling produces resolves to no discovery document, which
           * is read as a sign-in starts, so the tenant's Keycloak sign-in fails
           * before the visitor reaches the realm at all. A value that is not
           * another spelling of the same issuer but a mistake — no scheme, or an
           * issuer already ending in the discovery path — is left to fail rather
           * than repaired. */
          .transform(issuer => issuer.replace(/\/+$/, '')),
      })
      .optional(),
  })
  .describe(
    "Per-tenant OAuth applications. Each provider is registered under the provider id '<provider>-<tenantId>' — register the matching redirect URI (/<tenantId>/api/auth/oauth2/callback/<provider>-<tenantId>, without the <tenantId> segment for a tenant reached on an origin of its own) with the identity provider. There is no global app: a tenant offers a provider only when it declares it here.",
  );

export const tenantConfigSchema = z.strictObject({
  sessionSecret: z
    .string()
    .min(1)
    .describe(
      "Signing and encryption secret for this tenant's sessions. Per tenant, not per deployment: each tenant authenticates through an instance of its own, so a secret that leaks forges sessions for that tenant alone. Generate a distinct long random value for every tenant (openssl rand -base64 32) — two tenants sharing one are refused.",
    ),
  routing: z
    .enum(['path', 'host'])
    .describe(
      `How this tenant's addresses are shaped. "path" (the default) carries the tenant id as the first path segment, e.g. https://portal.example.com/acme/sales, and the origin may be shared with other tenants. "host" drops that segment and lets ${name([TENANTS_KEY, '<id>', 'public', 'host'])} name the tenant instead, e.g. https://acme.example.com/sales. "host" needs a host no other tenant is served on, and a proxy that sets X-Forwarded-Host (or Host) to the address the visitor used rather than the address of the server behind it — nginx sends its own upstream address by default, and a deployment left that way resolves no tenant and refuses every form submission. Changing this changes every address the tenant is reached at: the stored workspace URLs, the registered OAuth redirect URIs and the links already sent out all carry the old shape.`,
    )
    .optional(),
  includeLanguage: z
    .boolean()
    .describe(
      "Also load the base language (e.g. 'en' for 'en-US') in addition to the specific locale. Defaults to false.",
    )
    .optional(),
  db: z.strictObject({
    url: z
      .string()
      .min(1)
      .describe(
        "Postgres connection URL of this tenant's own database. Every tenant has its own database; isolation is per-database.",
      ),
  }),
  aos: aosSchema,
  payments: paymentsSchema.optional(),
  mail: mailSchema.optional(),
  mattermost: z
    .strictObject({
      token: z.string().describe('Mattermost admin token.').optional(),
      createUsers: z
        .boolean()
        .describe('Create Mattermost users on registration.')
        .optional(),
    })
    .describe(
      `Mattermost integration. The address the browser links to is browser-facing and lives under ${name([TENANTS_KEY, '<id>', 'public', 'mattermost', 'host'])}.`,
    )
    .optional(),
  oauth: oauthSchema.optional(),
  webPush: z
    .strictObject({
      privateKey: z.string().min(1),
      subject: z
        .string()
        .min(1)
        .describe(
          'mailto: address or https: URL identifying the sender to push services.',
        ),
    })
    .describe(
      `Web-push signing identity; the public key lives under ${name([TENANTS_KEY, '<id>', 'public', 'webPush', 'publicKey'])}. The service worker registers once per tenant — under the tenant path segment where several tenants share an origin, and at the root of the origin where the tenant has one to itself — so each tenant holds its own push subscription and its own key pair takes effect either way.`,
    )
    .optional(),
  upload: z
    .strictObject({
      recordRetentionHours: z
        .number()
        .describe(
          'How long terminal staged-upload records are kept before the prune sweep deletes them. Defaults to 168 (7 days).',
        )
        .optional(),
    })
    .optional(),
  public: publicConfigSchema,
});

/**
 * The settings bound to the single process rather than to a tenant.
 */
export const deploymentConfigSchema = z.strictObject({
  origin: z
    .string()
    .min(1)
    .refine(isDeploymentOrigin, {error: ORIGIN_ERROR})
    .describe(
      `Origin serving the addresses that name no tenant — "/" and the deployment's own routes under /deployment — e.g. https://portal.example.com, scheme and host only with no trailing slash. Every tenant's own origin (${name([TENANTS_KEY, '<id>', 'public', 'host'])}) is trusted for authentication alongside it, and a request arriving on a host none of them names is answered under this one. Its scheme decides whether the deployment's session cookies are written as __Secure-, so every origin in the configuration has to share it.`,
    ),
  defaultTenant: z
    .string()
    .min(1)
    .describe(
      'Tenant serving the addresses that name none of their own: "/", and a script run with no --tenant. Must name a configured tenant. A deployment configuring one tenant leaves this out — that tenant is the only answer and is filled in. Beyond one it is required as soon as any tenant is reached under a path segment, since "/" on the origin such a tenant is served on names no tenant. A deployment whose tenants are all reached by host may leave it out; each tenant then answers "/" on the origin it holds, a script needs --tenant, and "/" on the deployment\'s own origin answers not-found unless a tenant holds that host too.',
    )
    .optional(),
  push: z
    .strictObject({
      maxConnections: positiveInteger()
        .describe(
          'Push deliveries in flight at once, and sockets held per push service. One agent serves the whole process, so this bounds the deployment. Defaults to 10.',
        )
        .optional(),
    })
    .optional(),
  imageCache: z
    .strictObject({
      maxBytes: positiveInteger()
        .describe(
          "Bytes the resized-image cache may occupy. One cache directory serves every tenant, so the budget is the deployment's.",
        )
        .optional(),
    })
    .optional(),
});

export type TenantConfig = z.output<typeof tenantConfigSchema>;
export type DeploymentConfig = z.output<typeof deploymentConfigSchema>;

/** What the browser is handed about a tenant: the `public` group, parsed. */
export type PublicConfig = TenantConfig['public'];

/* The shapes as they are written, before the parse settles the storage root and
 * the Keycloak issuer. What writes configuration rather than reads it — the
 * environment migration — builds these, which match the parsed ones only for as
 * long as no setting is given a default or a coercion. */
export type TenantConfigInput = z.input<typeof tenantConfigSchema>;
export type DeploymentConfigInput = z.input<typeof deploymentConfigSchema>;

type TenantEntry = [string, TenantConfig];

/* A violated configuration-wide invariant, reported against the setting that
 * has to change rather than against the configuration as a whole. */
type ConfigIssue = {path: string[]; message: string};

const tenantPath = (id: string, ...keys: string[]) => [
  TENANTS_KEY,
  id,
  ...keys,
];

/* Cross-tenant invariant. A HUB PISP tenant authenticates to BPCE with an mTLS
 * client certificate loaded from its certsDir (client.crt + private-key.pem) —
 * that certificate IS the tenant's enrolled bank identity, so two tenants must
 * never resolve to the same certsDir or they would transact as the same bank
 * client. certsDir is required per tenant, so this only has to reject two
 * tenants that point at the same directory. Paths are resolved to absolute so
 * equivalent specs (relative vs absolute, trailing slash) compare equal. */
function checkHubPispCertIsolation(tenants: TenantEntry[]): ConfigIssue[] {
  const issues: ConfigIssue[] = [];
  const byCertsDir = new Map<string, string>(); // resolved certsDir -> tenant id

  for (const [id, config] of tenants) {
    const configured = config.payments?.hubpisp?.certsDir;
    if (!configured) continue;

    const certsDir = path.resolve(configured);
    const owner = byCertsDir.get(certsDir);

    if (owner) {
      issues.push({
        path: tenantPath(id, 'payments', 'hubpisp', 'certsDir'),
        message:
          `Tenants "${owner}" and "${id}" share the same HUB PISP certsDir ` +
          `("${certsDir}"). Each HUB PISP tenant needs its own mTLS client ` +
          `certificate — give each a directory of its own.`,
      });
      continue;
    }

    byCertsDir.set(certsDir, id);
  }

  return issues;
}

/* Cross-tenant invariant. Uploads are recorded as a path relative to the tenant's
 * storage root, so two tenants resolving to the same root share one namespace:
 * each would resolve the other's recorded paths, and the retention sweep would
 * delete from a directory holding another tenant's blobs. The roots compared here
 * are the resolved ones — a tenant on a shared AOS already has its AOS tenant id
 * subdirectory baked in — so tenants sharing one AOS legitimately pass. */
function checkStorageIsolation(tenants: TenantEntry[]): ConfigIssue[] {
  const issues: ConfigIssue[] = [];
  const roots: Array<[string, string]> = []; // [tenant id, resolved storage root]

  for (const [id, config] of tenants) {
    const storage = path.resolve(config.aos.storage);

    for (const [owner, existing] of roots) {
      /* Containment, not just equality: a tenant that keeps the base path (no
       * AOS tenant id) while another sits in a subdirectory of it would otherwise
       * pass, and the outer tenant's root then contains the inner one's — its
       * recorded paths resolve into the inner tenant's files and its retention
       * sweep deletes from them. */
      const nested =
        storage === existing ||
        storage.startsWith(existing + path.sep) ||
        existing.startsWith(storage + path.sep);

      if (nested) {
        issues.push({
          path: tenantPath(id, 'aos', 'storage'),
          message:
            `Tenants "${owner}" ("${existing}") and "${id}" ("${storage}") share ` +
            `a storage root — one contains the other. Give each tenant a ` +
            `directory of its own, or set ${name(tenantPath('<id>', 'aos', 'tenantId'))} ` +
            `on every tenant that shares one AOS instance.`,
        });
      }
    }

    roots.push([id, storage]);
  }

  return issues;
}

/* Cross-tenant invariant. A tenant's signing key is what keeps its sessions its
 * own: a cookie is named for one tenant and opened with that tenant's key, so a
 * key belonging to one tenant alone is what makes a cookie of another tenant's
 * unreadable. Shared, the two tenants can open each other's sessions, and a
 * cookie renamed from one to the other is then accepted — read as the tenant its
 * payload names, which chooses the database, while the address chose the
 * instance. The session guard in lib/auth.ts refuses that mismatch; this refuses
 * the configuration that makes it reachable. */
function checkSecretIsolation(tenants: TenantEntry[]): ConfigIssue[] {
  const issues: ConfigIssue[] = [];
  const owners = new Map<string, string>();

  for (const [id, config] of tenants) {
    const secret = config.sessionSecret;
    const owner = owners.get(secret);

    if (owner) {
      issues.push({
        path: tenantPath(id, 'sessionSecret'),
        message:
          `Tenants "${owner}" and "${id}" share a session secret. Each tenant ` +
          `signs its own sessions, so a shared key lets either open the other's. ` +
          `Generate one per tenant with: openssl rand -base64 32`,
      });
    } else {
      owners.set(secret, id);
    }
  }

  return issues;
}

/* Cross-tenant invariant. Tenants sharing one mail account share one connection
 * pool, so they must agree on how many connections that account allows: the pool
 * is built by whichever tenant sends first, and a disagreement would make the
 * ceiling depend on send order — intermittently exceeding the limit the lower
 * value was set to respect. */
function checkMailCeilings(tenants: TenantEntry[]): ConfigIssue[] {
  const issues: ConfigIssue[] = [];
  const byAccount = new Map<string, {id: string; maxConnections: number}>();

  for (const [id, config] of tenants) {
    const mail = config.mail;
    if (!mail?.host) continue;

    const account = mailAccountKey(mail);
    const existing = byAccount.get(account);

    /* Compared as they are applied, not as they are written: leaving the setting
     * out means the default, so a tenant that omits it agrees with one that
     * spells that same number out. Refusing those would make an operator state
     * what the two configurations already mean. */
    const maxConnections = getMaxConnections(mail);

    if (existing && existing.maxConnections !== maxConnections) {
      issues.push({
        path: tenantPath(id, 'mail', 'maxConnections'),
        message:
          `Tenants "${existing.id}" and "${id}" share the mail account ` +
          `"${mail.user}" on ${mail.host} but allow it a different number of ` +
          `connections (${existing.maxConnections} and ${maxConnections}). ` +
          `They share one connection pool, so the ceiling must match — set ` +
          `${name(tenantPath('<id>', 'mail', 'maxConnections'))} to the same value for both.`,
      });
      continue;
    }

    if (!existing) {
      byAccount.set(account, {id, maxConnections});
    }
  }

  return issues;
}

/*
 * Checked against the tenants, because the two are configured separately.
 * Rename or drop a tenant and this can be left pointing at one that is not
 * there, and the addresses it serves answer not-found with no explanation.
 *
 * Required where a tenant is reached under a path segment, because such a
 * tenant sits on an origin whose own `/` serves no tenant: a visitor who types
 * the bare origin arrives at the deployment's entry, which has nothing to
 * resolve without this and answers not-found. `checkHostRouting` refuses a
 * path-routed tenant sharing a host with a host-routed one, so routing alone
 * never gives such an origin a tenant to answer its `/` — where this is
 * demanded, the unclaimed address is really there, and naming a tenant here is
 * what answers it.
 *
 * A deployment whose tenants are all reached by host is exempt. Its own origin
 * may still have an unanswered `/`, where no tenant holds that host, but that
 * is an infrastructure address — it carries `/deployment` and the sign-in
 * fallback, and a tenant address reached there is sent to the tenant's own
 * origin — so an operator is left to decide whether `/` on it leads anywhere
 * rather than made to hand it to one tenant of several.
 *
 * A single-tenant deployment declares nothing either way: one tenant is the
 * only answer, so the loader fills it in.
 *
 * A tenant that omits `routing` is path-routed, which is what the filter below
 * reads. A value that is neither spelling is refused by the property's own
 * type, which stops the configuration before this runs — unlike a failed
 * refinement, which arrives here with its value in place — so the routing seen
 * here is always one the tenant validly declared.
 */
function checkDefaultTenant(
  defaultTenant: string | undefined,
  tenants: TenantEntry[],
): ConfigIssue[] {
  const ids = tenants.map(([id]) => id);

  if (defaultTenant) {
    if (ids.includes(defaultTenant)) {
      return [];
    }

    return [
      {
        path: ['defaultTenant'],
        message:
          `"${defaultTenant}" names no configured tenant; the tenants are ` +
          `${ids.join(', ')}.`,
      },
    ];
  }

  if (ids.length < 2) {
    return [];
  }

  const pathRouted = tenants
    .filter(([, config]) => config.routing !== 'host')
    .map(([id]) => id);

  if (!pathRouted.length) {
    return [];
  }

  return [
    {
      path: ['defaultTenant'],
      message:
        `is required: ` +
        (pathRouted.length === 1
          ? `tenant "${pathRouted[0]}" is reached under a path segment, so ` +
            `"/" on the origin it is served on names no tenant.`
          : `tenants ${pathRouted.join(', ')} are reached under a path ` +
            `segment, so "/" on the origins they are served on names no ` +
            `tenant.`) +
        ` Name the tenant "/" leads to; the tenants are ${ids.join(', ')}.`,
    },
  ];
}

/* Cross-tenant invariant. The auth cookie names are settled once, as the auth
 * instance is built, from the scheme the deployment origin carries, so one
 * naming serves every origin in the configuration and the schemes have to
 * agree. Where they do not: an http tenant under an https deployment is sent
 * `__Secure-` cookies a browser refuses over http and holds no session at all,
 * and an https tenant under an http deployment is sent cookies carrying neither
 * the prefix nor the Secure attribute. Both are refused. */
function checkOriginSchemes(
  deploymentOrigin: unknown,
  tenants: TenantEntry[],
): ConfigIssue[] {
  const deployment = parseOrigin(deploymentOrigin);

  /* Nothing to compare the tenants against, and the setting's own check has
   * already reported why. Reporting a mismatch against a scheme that could not
   * be read would add a second fault to a configuration whose only fault is
   * this one. The tenants need no such guard: a tenant whose own origin was
   * refused does not reach here. */
  if (!deployment) return [];

  return tenants.flatMap(([id, config]) => {
    const declared = config.public.host;

    /* Null only in principle, for the reason above, but the type says it can be
     * and reading a scheme off it unchecked is what would throw. */
    const origin = parseOrigin(declared);

    if (!origin || origin.protocol === deployment.protocol) return [];

    return [
      {
        path: tenantPath(id, 'public', 'host'),
        message:
          `Tenant "${id}" is served on ${declared} while the deployment is ` +
          `served on ${deployment.origin}. Both have to use the same scheme — ` +
          `serve every origin over ${deployment.protocol.replace(':', '')}, or ` +
          `change ${name(['origin'])} to match.`,
      },
    ];
  });
}

/* Cross-tenant invariant. A host-routed tenant is named by the host it is served
 * on, so nothing else may be served on that host: the tenant segment is put back
 * on before the path is read, so whatever else was reached there has its own
 * first segment taken for one of this tenant's workspaces.
 *
 * Three claimants can collide on one host, and hosts are compared rather than
 * whole origins because a request carries no scheme to tell two apart:
 *
 * - another host-routed tenant, which leaves the host naming neither in
 *   particular;
 * - a path-routed tenant, whose own segment stops resolving;
 * - the addresses naming no tenant, where the default tenant says "/" leads
 *   somewhere other than the tenant holding that host.
 *
 * The last of those is refused only when the two disagree. A host-routed tenant
 * on the deployment origin's own host is the ordinary single-tenant deployment —
 * one tenant, holding every address of the origin it is served on, reached
 * without a tenant segment — and "/" leading to it is what an operator asked
 * for. It becomes a conflict only where the default tenant names a different
 * tenant, which is two answers to what "/" means on one host.
 *
 * Refused rather than resolved by an order of preference: a deployment where
 * which tenant answers depends on the order tenants happen to be declared in is
 * worse than one that will not start. */
function checkHostRouting(
  deploymentOrigin: unknown,
  defaultTenant: string | undefined,
  tenants: TenantEntry[],
): ConfigIssue[] {
  const issues: ConfigIssue[] = [];

  /* Keyed by `canonicalHost` — the spelling request routing compares with — so
   * what this refuses as claimed twice is exactly what would collide in the
   * routing index built from the same configuration. */
  const byHost = new Map<string, string>(); // host -> host-routed tenant id

  for (const [id, config] of tenants) {
    if (config.routing !== 'host') continue;

    const origin = parseOrigin(config.public.host);

    /* Null only in principle — a tenant whose own origin was refused does not
     * reach here — but reading a host off it unchecked is what would throw. */
    if (!origin) continue;

    const owner = byHost.get(canonicalHost(origin.host));

    if (owner) {
      issues.push({
        path: tenantPath(id, 'public', 'host'),
        message:
          `Tenants "${owner}" and "${id}" are both routed by host and both ` +
          `served on the host ${origin.host}, so a request arriving there names ` +
          `neither of them. Give each host-routed tenant a host of its own, or ` +
          `set ${name(tenantPath('<id>', 'routing'))} to path on one of them.`,
      });
      continue;
    }

    byHost.set(canonicalHost(origin.host), id);
  }

  for (const [id, config] of tenants) {
    if (config.routing === 'host') continue;

    const origin = parseOrigin(config.public.host);

    if (!origin) continue;

    const owner = byHost.get(canonicalHost(origin.host));

    if (owner) {
      issues.push({
        path: tenantPath(id, 'public', 'host'),
        message:
          `Tenant "${id}" is served on ${origin.origin} under a tenant path ` +
          `segment, but "${owner}" is routed by host on that same host, so ` +
          `/${id} there is read as one of "${owner}"'s workspaces. Serve "${id}" ` +
          `on another host, or route it by host too.`,
      });
    }
  }

  const deployment = parseOrigin(deploymentOrigin);
  const deploymentOwner =
    deployment && byHost.get(canonicalHost(deployment.host));

  if (deploymentOwner && defaultTenant && defaultTenant !== deploymentOwner) {
    issues.push({
      path: ['defaultTenant'],
      message:
        `"/" on ${deployment.origin} is claimed twice: "${deploymentOwner}" is ` +
        `routed by host there, so it answers every address of that origin, while ` +
        `${name(['defaultTenant'])} sends "/" to "${defaultTenant}". Name ` +
        `"${deploymentOwner}" there, or serve "${deploymentOwner}" on a host of ` +
        `its own. Leaving it unset works only where no tenant is reached under ` +
        `a path segment, which requires one.`,
    });
  }

  return issues;
}

function checkTenantIds(ids: string[]): ConfigIssue[] {
  const issues: ConfigIssue[] = [];

  for (const id of ids) {
    if (!TENANT_ID_PATTERN.test(id)) {
      issues.push({
        path: tenantPath(id),
        message:
          `"${id}" is not a usable tenant id. A tenant id is the URL path ` +
          `segment it is served under and the segment of every variable that ` +
          `configures it: a lowercase letter, then lowercase letters or digits.`,
      });
      continue;
    }

    if (isReservedSegment(id)) {
      issues.push({
        path: tenantPath(id),
        message:
          `"${id}" cannot be a tenant id: the deployment answers /${id} ` +
          `itself, so no request would reach a tenant named this. Reserved: ` +
          `${reservedSegments().join(', ')}.`,
      });
      continue;
    }

    if (id.length > TENANT_ID_MAX_LENGTH) {
      issues.push({
        path: tenantPath(id),
        message:
          `"${id}" is ${id.length} characters, and a tenant id may hold at ` +
          `most ${TENANT_ID_MAX_LENGTH}. A Hub PISP payment carries its ` +
          `reference as "<paymentContextId>-<tenantId>" in a field of 35 ` +
          `characters, and a context id can reach 19 digits, so a longer id ` +
          `works until this tenant's context ids grow and then fails every Hub ` +
          `PISP payment it attempts.`,
      });
    }
  }

  return issues;
}

/*
 * The whole configuration: the deployment's settings, plus one entry per tenant
 * under `tenants`, keyed by tenant id.
 *
 * The tenant ids are a record's keys rather than declared properties, which is
 * what lets an operator name their own tenants; the load enforces what an id may
 * be below, where the message can say what an id is for.
 */
export const configSchema = z
  .strictObject({
    ...deploymentConfigSchema.shape,
    [TENANTS_KEY]: z.record(z.string(), tenantConfigSchema),
  })
  /* These see a configuration that parsed — a setting of the wrong type, a
   * missing one, or a name no group declares stops the parse before this — but
   * not one every setting accepted. A failed refinement leaves its value in
   * place and the configuration still arrives here, so a check can read a
   * setting a refinement has just rejected; and a transform behind a failed
   * refinement has not run, so a value can arrive neither as written nor as the
   * application would use it. A tenant on a shared AOS instance whose
   * credentials were refused is the case that occurs: its storage root arrives
   * as written rather than as the per-tenant subdirectory of it the application
   * uses, which reads as a tenant holding the directory its neighbours sit in.
   *
   * So the checks comparing tenants against each other are given only the
   * tenants whose own settings reported nothing. Comparing against a value that
   * is not the one the application will use reports a collision against
   * whichever tenant is configured correctly, sending an operator to change
   * the entry that is already right. A collision that a skipped tenant is
   * genuinely part of is reported once its own fault is fixed. */
  .check(ctx => {
    const tenants = Object.entries(ctx.value[TENANTS_KEY]) as TenantEntry[];

    const ids = tenants.map(([id]) => id);

    /* Every issue raised so far carries the path it belongs to, and a tenant's
     * id is the second segment of a path under `tenants`. */
    const faulted = new Set(
      ctx.issues
        .filter(issue => issue.path?.[0] === TENANTS_KEY)
        .map(issue => issue.path?.[1])
        .filter((segment): segment is string => typeof segment === 'string'),
    );

    /* The ids stay whole: what a tenant is named, and whether the default names
     * one, is answered by the keys and holds however the entry under a key
     * fared. */
    const settled = tenants.filter(([id]) => !faulted.has(id));

    const issues = [
      ...checkTenantIds(ids),
      ...(tenants.length
        ? [
            /* The tenants whole, not `settled`: what a tenant is named, and
             * how it is routed, is answered by its own entry however the rest
             * of that entry fared. */
            ...checkDefaultTenant(ctx.value.defaultTenant, tenants),
            ...checkOriginSchemes(ctx.value.origin, settled),
            ...checkHostRouting(
              ctx.value.origin,
              ctx.value.defaultTenant,
              settled,
            ),
            ...checkHubPispCertIsolation(settled),
            ...checkSecretIsolation(settled),
            ...checkStorageIsolation(settled),
            ...checkMailCeilings(settled),
          ]
        : [
            {
              path: [TENANTS_KEY],
              message:
                `No tenant is configured. Every tenant is declared by its ` +
                `variables, ${name([TENANTS_KEY, '<id>'])}_…; see env.example.`,
            },
          ]),
    ];

    for (const issue of issues) {
      ctx.issues.push({
        code: 'custom',
        input: ctx.value,
        path: issue.path,
        message: issue.message,
      });
    }
  });

export type Config = z.output<typeof configSchema>;
export type ConfigInput = z.input<typeof configSchema>;
